{"content": "from fastapi import FastAPI, Depends, Security, SecurityScopes
from fastapi.testclient import TestClient
from typing import List

app = FastAPI()

def get_a(security_scopes: SecurityScopes):
    return security_scopes.scopes

def get_a1(security_scopes: SecurityScopes):
    return security_scopes.scopes

def get_a2(security_scopes: SecurityScopes):
    return security_scopes.scopes

def get_root(a: str = Security(get_a, scopes=["a"]), 
              a1: str = Security(get_a1, scopes=["a1"]), 
              a2: str = Security(get_a2, scopes=["a2"])):
    return {"a": a, "a1": a1, "a2": a2}

# This is not quite right because get_a, get_a1, get_a2 are not dependencies of each other.
# I need a hierarchy.

def dep_a(security_scopes: SecurityScopes):
    return security_scopes.scopes

def dep_a1(a: list = Security(dep_a, scopes=["a"]), security_scopes: SecurityScopes):
    return security_scopes.scopes

def dep_a2(a: list = Security(dep_a, scopes=["a"]), security_scopes: SecurityScopes):
    return security_scopes.scopes

def root(a1: list = Security(dep_a1, scopes=["a1"]), a2: list = Security(dep_a2, scopes=["a2"])):
    return {"a1": a1, "a2": a2}

# Wait, the above is also not quite right. 
# Let's try:
# root depends on dep_a1 and dep_a2.
# dep_a1 depends on dep_a.
# dep_a2 depends on dep_a.

def dep_a(security_scopes: SecurityScopes):
    return security_scopes.scopes

def dep_a1(a=Security(dep_a, scopes=["a"]), security_scopes: SecurityScopes):
    return security_scopes.scopes

def dep_a2(a=Security(dep_a, scopes=["a"]), security_scopes: SecurityScopes):
    return security_scopes.scopes

@app.get("/")
def root(a1=Security(dep_a1, scopes=["a1"]), a2=Security(dep_a2, scopes=["a2"])):
    return {"a1": a1, "a2": a2}

client = TestClient(app)

def test_scopes():
    response = client.get("/")
    print(response.json())
    # Expected: a1: ['a1', 'a'], a2: ['a2', 'a']
    # If bug exists: a1: ['a1', 'a'], a2: ['a2', 'a', 'a1'] (or something similar)

if __name__ == "__main__":
    test_scopes()
", "filepath": "reproduce_issue.py"}

